SELECT DATE_FORMAT(s.started_at, 'yyyy-MM') started_month, CASE WHEN s.device IN ('desktop', 'tablet') THEN 'tier_1' ELSE 'other' END device_group, COUNT(CASE WHEN we.page = '/cart' THEN 1 END) cart_count FROM web_events we INNER JOIN sessions s ON we.session_id = s.id LEFT JOIN customers c ON s.customer_id = c.id WHERE c.signup_date <= '2025-05-01' GROUP BY DATE_FORMAT(s.started_at, 'yyyy-MM'), CASE WHEN s.device IN ('desktop', 'tablet') THEN 'tier_1' ELSE 'other' END ORDER BY device_group, started_month DESC
